def max_sum_increasing_subseq(arr, n, i, k):
    dp = [0] * (i + 1)
    for j in range(i + 1):
        dp[j] = arr[j]
        for p in range(j):
            if arr[p] < arr[j] and dp[p] + arr[j] > dp[j]:
                dp[j] = dp[p] + arr[j]
    best = -1
    for j in range(i + 1):
        if arr[j] < arr[k]:
            best = max(best, dp[j] + arr[k])
    return best
