def check_expression(expression):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in expression:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            return False
    return not stack
